x0 = 0.7
b = 0.1


def f(x):
    return x**3/(np.exp(x)-1)

def w(x):
    return 1/(b + (x-x0)**2)

def get_x(y): 
    return x0 + np.sqrt(b)*np.tan((np.sqrt(b))*y)

def g(x):
    return (x**3) * (b + (x-x0)**2)/(np.exp(x)-1)

def MC_eval_f(n):
    store = 0.0
    for i in range(n):
        x = np.random.rand()
        store += f(x)
    return store/n

def MC_eval_g(n):
    store = 0.0
    for i in range(n):
        y = np.random.rand()
        store += g(get_x(y))
    return store/n

